import axios from "axios";
import { useEffect, useState } from "react";

const Users = () => {
  const getUsers = async () => {
    const response = await axios.get("http://localhost:5000/names");
    console.log(response.data);
  };
  useEffect(() => {
    getUsers();
  }, []);

  return (
    <div>
      <h3>Merch Comm</h3>
    </div>
  );
};

export default Users;
